    {"id":"SRC-BOLOGNA-CLE-ABOUT","university_id":"bologna","title":"About CLE – consortium programme overview","url":"https://cle.unibo.it/pages/8/about-cle","source_type":"Official joint-master programme overview","accessed_at":AS_OF,"cycle":"general","evidence":"Describes a two-year joint programme across eight partner universities, with mobility at two or three locations and a double or multiple Master's degree. The language of teaching varies by partner university; Bologna is the coordinating partner and is one of the teaching locations.","supports":["program.duration","program.campus","program.teaching_language","program.degree_structure"]},
