    {"id":"SRC-MILANO-CONTACT","university_id":"milano-statale","title":"Welcome Desk – International Admissions and Credentials Evaluation","url":"https://www.unimi.it/en/study/student-services/welcome-desk-informastudenti","source_type":"Official international admissions contact page","accessed_at":AS_OF,"cycle":"general","evidence":"The University directs applicants who are not resident in Italy or hold foreign qualifications to the International Admissions and Credentials Evaluation Office through InformaStudenti. General contact route only.","supports":["university.admissions_contact","university.application_portal"]},
